    id: product.id,
    title: product.title,
    description: product.description,
    brandId: product.brandId,
    brandName: product.brandName,
    categoryId: product.categoryId,
    categoryName: product.categoryName,
    price: product.price,
    originalPrice: product.originalPrice,
    status: product.status
